insert into steps (id, block_id, position, text, finished) values
  ('s-0', 'store:instr', 0, 'Set the six display tables in a U, opening to the main aisle.', false),
  ('s-1', 'store:instr', 1, 'Build the three tills behind the display line.', false),
  ('s-2', 'store:instr', 2, 'Patch each till to the network drop at the rear wall.', false),
  ('s-3', 'store:instr', 3, 'Hang both banners, bottom edge at 2.4 m.', false),
  ('s-4', 'store:instr', 4, 'Stock the display tables from the pallets, largest sizes at the back.', false),
  ('s-c', 'customer:instr', 0, 'Set both desks facing the entrance aisle.', true),
  ('s-d', 'customer:instr', 1, 'Patch the two laptops to the wall drop and test the ticket system.', true),
  ('s-e', 'customer:instr', 2, 'Stock the lost property bins under desk two.', true),
  ('s-f', 'customer:instr', 3, 'Hang the desk sign at 2.2 m.', true),
  ('s-s', 'goodie-booth:instr', 0, 'Set the four distribution counters in a straight line, 1.2 m apart, facing the concourse.', false),
  ('s-t', 'goodie-booth:instr', 1, 'Skirt every counter front, pleats facing the public side.', false),
  ('s-u', 'goodie-booth:instr', 2, 'Stage two pallets of filled bags behind each pair of counters. Nothing in the queue lane.', false),
  ('s-v', 'goodie-booth:instr', 3, 'Patch the four scan tablets to the access point and test one pick-up end to end.', false),
  ('s-w', 'goodie-booth:instr', 4, 'Hang the overhead sign at 2.6 m, centred on counters two and three.', false),
  ('s-x', 'goodie-booth:instr', 5, 'Run the queue as a single serpentine, eight posts, belts at half tension.', false),
  ('s-y', 'goodie-booth:instr', 6, 'Call room 208 for a pallet refill at two pallets remaining. Do not let a counter run empty.', false),
  ('s-19', 'pod-wm:instr', 0, 'Bolt the four podium steps together, fourth step at the right, and level them on the mat.', false),
  ('s-1a', 'pod-wm:instr', 1, 'Set the backdrop frame 1.5 m behind the podium, centred on the photographer riser.', false),
  ('s-1b', 'pod-wm:instr', 2, 'Place the three medal tables stage right, trays in belt order.', false),
  ('s-1i', 'pod-jjc:instr', 0, 'Bolt the three podium steps together and level them on the mat.', true),
  ('s-1j', 'pod-jjc:instr', 1, 'Set the backdrop frame 1.5 m behind the podium, centred.', true),
  ('s-1k', 'pod-jjc:instr', 2, 'Place the two medal tables stage right, trays in order.', false),
  ('s-1l', 'pod-jjc:instr', 3, 'Tape the athlete walk-on line in gold from the tunnel to step 1.', false),
  ('s-1m', 'pod-jjc:instr', 4, 'Stand on each step before handover. Nothing should rock.', false),
  ('s-27', 'champ-wm:instr', 0, 'The World Master floor is built on the Jiu-Jitsu Con floor. Lift areas 9 to 12 first, then re-tape 1 to 8.', false),
  ('s-28', 'champ-wm:instr', 1, 'Re-mark areas 1 to 8 as World Master areas and swap the area signage.', false),
  ('s-29', 'champ-wm:instr', 2, 'Set one mat control table per area, laptop and scoreboard facing the referee.', false),
  ('s-2a', 'champ-wm:instr', 3, 'Patch every control laptop to the floor switch and run a test bracket on each area.', false),
  ('s-2b', 'champ-wm:instr', 4, 'Walk every seam before handover. No gap wider than a finger.', false),
  ('s-2m', 'rooms:instr', 0, 'Collect the key set for rooms 201 to 208 from the venue office.', false),
  ('s-2n', 'rooms:instr', 1, 'Set each room to its sheet: table count, chair count and layout.', false),
  ('s-2o', 'rooms:instr', 2, 'Fit the room name card in the holder outside each door.', false),
  ('s-2p', 'rooms:instr', 3, 'Build the projector kits in 202, 204, 206 and 208 and test the laptop feed.', false),
  ('s-2q', 'rooms:instr', 4, 'Place a water station on each landing, two per side.', false),
  ('s-2r', 'rooms:instr', 5, 'Photograph each finished room and mark it complete on the phone.', false),
  ('s-2x', 'carpet:install', 0, 'Sweep the slab and mark the six zone boundaries with tape.', true),
  ('s-2y', 'carpet:install', 1, 'Roll carpet zone by zone, starting at the north wall.', true),
  ('s-2z', 'carpet:install', 2, 'Tape every seam on both edges. No loose edge in a walkway.', true),
  ('s-30', 'carpet:install', 3, 'Fit edge trim on all aisle transitions.', true),
  ('s-36', 'pipe:install', 0, 'Set base plates every 3 m along the marked perimeter.', false),
  ('s-37', 'pipe:install', 1, 'Raise uprights and level before any drape goes on.', false),
  ('s-38', 'pipe:install', 2, 'Hang drape at 3 m, pleats facing the public side.', false),
  ('s-39', 'pipe:install', 3, 'Tie back the two service gaps marked on the plan.', false),
  ('s-3w', 'power:install', 0, 'Confirm the twelve drop positions against the plan before pulling cable.', true),
  ('s-3x', 'power:install', 1, 'Set distro boxes at drops 2, 5 and 9.', true),
  ('s-3y', 'power:install', 2, 'Run extension cords to the sector tables, cable ramps on every crossing.', true),
  ('s-3z', 'power:install', 3, 'Label both ends of every cord with its drop number.', false),
  ('s-40', 'power:install', 4, 'Load test each drop and record the reading.', false),
  ('s-46', 'internet:install', 0, 'Confirm the eighteen drop positions against the plan before pulling cable.', false),
  ('s-47', 'internet:install', 1, 'Pull from the hall MDF, one run per drop, and label both ends with the drop number.', false),
  ('s-48', 'internet:install', 2, 'Terminate and test each drop with the house IT technician present.', false),
  ('s-49', 'internet:install', 3, 'Mount the twelve access points at 3 m. Never on a table or a counter.', false),
  ('s-4a', 'internet:install', 4, 'Bring the event SSID live and walk the hall for coverage gaps.', false),
  ('s-4b', 'internet:install', 5, 'Log the speed test for every drop on work order 4471.', false),
  ('s-4i', 'truss:instr', 0, 'Verify all 26 hang points against the certified rigging plan before anything is lifted.', true),
  ('s-4j', 'truss:instr', 1, 'Fit span sets and safety steels at every point.', true),
  ('s-4k', 'truss:instr', 2, 'Lay the truss sections out on the deck under their own points.', true),
  ('s-4l', 'truss:instr', 3, 'Attach the mat banners to the truss before it goes up. Never at height.', true),
  ('s-4m', 'truss:instr', 4, 'Raise to 6 m in one pass, all points together.', false),
  ('s-4n', 'truss:instr', 5, 'Check banner alignment from the bleacher side and lock off.', false),
  ('s-4o', 'truss:instr', 6, 'Sign the rig off with the venue rigger before any further load goes up.', false),
  ('s-4s', 'truck:instr', 0, 'Stage the four bays before the first truck backs in.', true),
  ('s-4t', 'truck:instr', 1, 'Unload bay by bay, sector labels facing out.', true),
  ('s-4u', 'truck:instr', 2, 'Move each crate straight to its sector. Nothing is stored on the dock.', true),
  ('s-4v', 'truck:instr', 3, 'Clear the dock plate area after every truck.', true),
  ('s-4w', 'truck:instr', 4, 'Log each truck off against the manifest as it leaves.', true),
  ('s-4x', 'staff:instr', 0, 'Collect the badge stock and lanyards from the set up desk.', true),
  ('s-4y', 'staff:instr', 1, 'Set the three check-in tables along the room 112 wall.', true),
  ('s-4z', 'staff:instr', 2, 'Open the check-in sheet and confirm the shift list against the roster.', true),
  ('s-50', 'staff:instr', 3, 'Brief the two desk staff on the check-out cut-off.', true),
  ('s-51', 'staff:instr', 4, 'Check every shift out on the sheet. Payroll works from that record alone.', true),
  ('s-52', 'bagline:instr', 0, 'Set the fourteen stations in two rows of seven, 1.5 m apart, with a clear 2 m run-out at the end of each row.', false),
  ('s-53', 'bagline:instr', 1, 'Place the bag cartons and the content pallets at the head of each row. Nothing in the walkway.', false),
  ('s-54', 'bagline:instr', 2, 'Load each station with one item type only, in the order the content list is printed.', false),
  ('s-55', 'bagline:instr', 3, 'Staff the line with 28 volunteers, two per station, plus one runner per row and one counter at the end.', false),
  ('s-56', 'bagline:instr', 4, 'Run ten bags as a test and check the item count against the content list before the line starts.', false),
  ('s-57', 'bagline:instr', 5, 'Start the line at 08:00. Target is 500 bags an hour, 6 000 bags by 20:00 on 26 Aug.', false),
  ('s-58', 'bagline:instr', 6, 'Break the line 12:00 to 12:30. The second shift takes over at 14:00.', false),
  ('s-59', 'bagline:instr', 7, 'Shrink-wrap each finished pallet at 250 bags and mark the count sheet.', false),
  ('s-5a', 'bagline:instr', 8, 'Move finished pallets to the Goodie Bag Booth from 07:00 on 26 Aug, six pallets per run.', false),
  ('s-5b', 'bagline:instr', 9, 'All 6 000 bags must be assembled and at the booth before doors at 09:00 on 26 Aug.', false),
  ('s-5j', 'sponsors:instr', 0, 'Drop each boxed kit at its booth number before sponsors arrive.', true),
  ('s-5k', 'sponsors:instr', 1, 'Build the counter unit and fit the branding panels at all nine booths.', false),
  ('s-5l', 'sponsors:instr', 2, 'Leave the kit instruction sheet on the counter.', false),
  ('s-5m', 'sponsors:instr', 3, 'Confirm power at every booth with the sponsor lead.', false),
  ('s-5n', 'sponsors:instr', 4, 'Walk the nine booths with the sponsor lead before doors.', false);
